 function consentHTML(d){const b=d.body,legal=legalConsent(b);return '<article class="su-document"><small>'+(legal?'수의사법 시행규칙 별지 제11호서식의 항목에 따른 전자 동의서':'진료 설명·동의서')+'</small><h1>'+(legal?'수술등중대진료 동의서':esc(b.title||'진료 동의서'))+'</h1><p class="su-status">'+esc(labels[d.status]||'작성 중')+(d.signedAt?' · '+stamp(d.signedAt):' · 서명 전 검토용')+'</p>'+(d.status==='void'?'<p class="su-warning">철회·사용 중지 · '+esc(d.voidReason)+'</p>':'')+'<dl class="su-info"><dt>동물 소유자·관리자</dt><dd>'+esc(b.guardianName)+' ('+esc(b.relationship)+')</dd><dt>연락처</dt><dd>'+esc(b.guardianPhone)+'</dd><dt>주소</dt><dd>'+esc(b.guardianAddress)+'</dd><dt>동물</dt><dd>'+esc(b.patientName)+' · '+esc(b.species)+' · '+esc(b.sex)+'</dd><dt>특이사항</dt><dd>'+esc(b.patientNotes||'미기재')+'</dd><dt>동물병원</dt><dd>'+esc(b.hospitalName)+'</dd><dt>설명 수의사</dt><dd>'+esc(b.doctorName)+' · 면허번호 '+esc(b.licenseNumber)+'</dd></dl><h2>설명 및 동의 사항</h2>'+(specialConsent(b)?sectionFields(b).map(([k,l])=>[l,b[k]]):[['진단명·의심되는 증상',b.diagnosis],['진료의 필요성·방법·내용',[b.necessity,b.method].filter(Boolean).join('\n\n')],['전형적으로 발생할 수 있는 후유증·부작용',b.risks],['진료 전후 보호자 준수사항',b.precautions]]).map(([l,v],i)=>'<section class="su-clause"><h3>'+(i+1)+'. '+l+'</h3><p>'+esc(v||'미기재')+'</p></section>').join('')+'<p>'+(legal?'「수의사법」 제13조의2 및 같은 법 시행규칙 제13조의2에 따라 위 내용에 대해 설명을 들었으며, 위와 같이 동의합니다.':(typeFields[b.kind]?.accept||'위 진료의 필요성·방법·부작용·주의사항을 설명받고 위 내용에 동의합니다.'))+'</p>'+(b.kind==='euthanasia'&&b.confirmations?.authorityConfirmed&&b.confirmations?.irreversibleConsented?'<p>소유자·위임 권한 및 가능한 대안과 회복 불가능성에 대한 설명·최종 동의 확인 완료</p>':'')+'<div class="su-signatures"><div><b>설명 수의사 '+esc(b.doctorName)+'</b>'+svg(b.signatures?.doctor)+'</div><div><b>동물 소유자·관리자 '+esc(b.guardianName)+'</b>'+svg(b.signatures?.guardian)+'</div></div><p>동의 일시: '+(d.signedAt?stamp(d.signedAt):'서명 완료 시 기록')+'</p><section class="su-annex"><h2>진료·비용 안내 기록</h2><dl class="su-info"><dt>진료명</dt><dd>'+esc(b.title)+'</dd><dt>'+(b.kind==='discharge'?'퇴원 예정 시각':b.kind==='admission'?'입원 예정 시각':'진료 시각')+'</dt><dd>'+esc(b.emergency?b.emergencyAt:b.plannedAt).replace('T',' ')+' (한국시간)</dd><dt>예상 비용·변동 안내</dt><dd>'+esc(b.cost)+'</dd>'+(b.emergency?'<dt>응급 사후 설명 사유</dt><dd>'+esc(b.emergencyReason)+'</dd>':'')+'<dt>병원 연락처</dt><dd>'+esc(b.hospitalPhone)+' · '+esc(b.hospitalAddress)+'</dd></dl><p class="su-small">서명 후 원본 내용은 변경되지 않습니다. 정정이 필요하면 새 동의서를 작성하며 원본과 연결합니다.</p></section><footer>문서 번호 '+esc(d.id||'임시 작성')+'<br>원본 확인값 '+esc(d.hash||'저장 후 생성')+(d.retainUntil?'<br>최소 보존 기한 '+stamp(d.retainUntil):'')+'</footer></article>';}
 function signature(canvas,onChange){const ctx=canvas.getContext('2d');let strokes=[],stroke=null;canvas.width=1200;canvas.height=320;const draw=()=>{ctx.clearRect(0,0,1200,320);ctx.strokeStyle='#123e49';ctx.lineWidth=4;ctx.lineCap='round';for(const line of strokes){ctx.beginPath();line.forEach((p,i)=>i?ctx.lineTo(p[0]*1200,p[1]*320):ctx.moveTo(p[0]*1200,p[1]*320));ctx.stroke();}};const point=e=>{const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))];};canvas.onpointerdown=e=>{if(e.button!==0||stroke)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);stroke=[point(e)];strokes.push(stroke);};canvas.onpointermove=e=>{if(!stroke)return;if(stroke.length<1500){stroke.push(point(e));draw();}};canvas.onpointerup=canvas.onpointercancel=()=>{if(stroke){if(stroke.length<2)strokes.pop();stroke=null;onChange();draw();}};return {value:()=>strokes,clear(){strokes=[];stroke=null;draw();onChange();}};}
 const resourceKinds=[['surgery','수술실'],['ultrasound','초음파실'],['equipment','장비 예약'],['other','기타 공간']];
